INSERT INTO public.courses (id, title, slug, description, category, level, thumbnail_url, instructor_id, is_published, created_at, updated_at) VALUES ('d0000000-0000-0000-0000-000000000001'::UUID, 'Python Programming: Beginner to Intermediate', 'python-programming-beginner-to-intermediate', 'Master foundational to intermediate Python programming: dynamic typing, control flow, functions, compound data structures, object-oriented design, error handling, and file I/O.', 'Computer Science', 'Beginner', 'https://images.unsplash.com/photo-1526374965328-7f61d4dc18c5?q=80&w=800&auto=format&fit=crop', 'c6086584-6cf7-43a4-ae1b-6bd3bb3f7293'::UUID, true, NOW(), NOW()) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, level = EXCLUDED.level, thumbnail_url = EXCLUDED.thumbnail_url, instructor_id = EXCLUDED.instructor_id, is_published = EXCLUDED.is_published, updated_at = NOW();
INSERT INTO public.courses (id, title, slug, description, category, level, thumbnail_url, instructor_id, is_published, created_at, updated_at) VALUES ('d0000000-0000-0000-0000-000000000002'::UUID, 'Java Programming and Object-Oriented Design', 'java-programming-object-oriented-design', 'Master enterprise Java: JVM architecture, object-oriented design patterns, inheritance, abstract classes, interfaces, checked exception architecture, generic collections, and multi-threading.', 'Computer Science', 'Intermediate', 'https://images.unsplash.com/photo-1517694712202-14dd9538aa97?q=80&w=800&auto=format&fit=crop', 'c6086584-6cf7-43a4-ae1b-6bd3bb3f7293'::UUID, true, NOW(), NOW()) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, level = EXCLUDED.level, thumbnail_url = EXCLUDED.thumbnail_url, instructor_id = EXCLUDED.instructor_id, is_published = EXCLUDED.is_published, updated_at = NOW();
INSERT INTO public.courses (id, title, slug, description, category, level, thumbnail_url, instructor_id, is_published, created_at, updated_at) VALUES ('d0000000-0000-0000-0000-000000000003'::UUID, 'Data Structures and Algorithms', 'data-structures-and-algorithms', 'Comprehensive undergraduate algorithms curriculum: asymptotic complexity, linear structures, trees, priority heaps, graph traversal, shortest path algorithms, dynamic programming, and greedy optimization.', 'Computer Science', 'Intermediate', 'https://images.unsplash.com/photo-1509228468518-180dd4864904?q=80&w=800&auto=format&fit=crop', 'c6086584-6cf7-43a4-ae1b-6bd3bb3f7293'::UUID, true, NOW(), NOW()) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, level = EXCLUDED.level, thumbnail_url = EXCLUDED.thumbnail_url, instructor_id = EXCLUDED.instructor_id, is_published = EXCLUDED.is_published, updated_at = NOW();
INSERT INTO public.courses (id, title, slug, description, category, level, thumbnail_url, instructor_id, is_published, created_at, updated_at) VALUES ('d0000000-0000-0000-0000-000000000004'::UUID, 'Full-Stack Web Development', 'full-stack-web-development', 'Modern full-stack web engineering: HTTP/1.1 to HTTP/3 protocols, semantic HTML5, responsive CSS Grid/Flexbox, ES6+ asynchronous JavaScript, React component hierarchies, state management, REST API architecture, and token security.', 'Web Development', 'Intermediate', 'https://images.unsplash.com/photo-1547658719-da2b51169166?q=80&w=800&auto=format&fit=crop', 'c6086584-6cf7-43a4-ae1b-6bd3bb3f7293'::UUID, true, NOW(), NOW()) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, level = EXCLUDED.level, thumbnail_url = EXCLUDED.thumbnail_url, instructor_id = EXCLUDED.instructor_id, is_published = EXCLUDED.is_published, updated_at = NOW();
INSERT INTO public.courses (id, title, slug, description, category, level, thumbnail_url, instructor_id, is_published, created_at, updated_at) VALUES ('d0000000-0000-0000-0000-000000000005'::UUID, 'Database Management Systems and SQL', 'database-management-systems-sql', 'Master relational database theory and modern SQL engineering: ER modeling, relational algebra, schema normalization (1NF to BCNF), complex multi-table joins, window functions, B-tree indexing, ACID transactions, and MVCC concurrency.', 'Database Engineering', 'Intermediate', 'https://images.unsplash.com/photo-1544383835-bda2bc66a55d?q=80&w=800&auto=format&fit=crop', 'c6086584-6cf7-43a4-ae1b-6bd3bb3f7293'::UUID, true, NOW(), NOW()) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, level = EXCLUDED.level, thumbnail_url = EXCLUDED.thumbnail_url, instructor_id = EXCLUDED.instructor_id, is_published = EXCLUDED.is_published, updated_at = NOW();
INSERT INTO public.courses (id, title, slug, description, category, level, thumbnail_url, instructor_id, is_published, created_at, updated_at) VALUES ('d0000000-0000-0000-0000-000000000006'::UUID, 'Operating Systems Fundamentals', 'operating-systems-fundamentals', 'Undergraduate operating systems engineering: kernel architecture, dual-mode operation, process lifecycles, CPU scheduling algorithms, synchronization primitives (semaphores, mutexes), deadlock characterization, virtual memory paging, and page replacement.', 'Computer Science', 'Intermediate', 'https://images.unsplash.com/photo-1629654297299-c8506221ca97?q=80&w=800&auto=format&fit=crop', 'c6086584-6cf7-43a4-ae1b-6bd3bb3f7293'::UUID, true, NOW(), NOW()) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, level = EXCLUDED.level, thumbnail_url = EXCLUDED.thumbnail_url, instructor_id = EXCLUDED.instructor_id, is_published = EXCLUDED.is_published, updated_at = NOW();
INSERT INTO public.courses (id, title, slug, description, category, level, thumbnail_url, instructor_id, is_published, created_at, updated_at) VALUES ('d0000000-0000-0000-0000-000000000007'::UUID, 'Computer Networks', 'computer-networks-principles', 'Comprehensive undergraduate computer networks curriculum: OSI 7-layer vs TCP/IP models, application protocols (HTTP/DNS), TCP reliability, sliding window, AIMD congestion control, IPv4/IPv6 CIDR subnetting, link-state routing, and network security.', 'Computer Science', 'Intermediate', 'https://images.unsplash.com/photo-1544197150-b99a580bb7a8?q=80&w=800&auto=format&fit=crop', 'c6086584-6cf7-43a4-ae1b-6bd3bb3f7293'::UUID, true, NOW(), NOW()) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, level = EXCLUDED.level, thumbnail_url = EXCLUDED.thumbnail_url, instructor_id = EXCLUDED.instructor_id, is_published = EXCLUDED.is_published, updated_at = NOW();
INSERT INTO public.courses (id, title, slug, description, category, level, thumbnail_url, instructor_id, is_published, created_at, updated_at) VALUES ('d0000000-0000-0000-0000-000000000008'::UUID, 'Software Engineering and Testing', 'software-engineering-and-testing', 'Undergraduate software engineering methodologies: SDLC models (Agile, Scrum, Waterfall), requirements engineering (SRS, IEEE 830), SOLID architectural design principles, black-box and white-box test design, TDD, CI/CD automation pipelines, and code review practices.', 'Software Architecture', 'Intermediate', 'https://images.unsplash.com/photo-1516116211227-bbc04c979bf7?q=80&w=800&auto=format&fit=crop', 'c6086584-6cf7-43a4-ae1b-6bd3bb3f7293'::UUID, true, NOW(), NOW()) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, level = EXCLUDED.level, thumbnail_url = EXCLUDED.thumbnail_url, instructor_id = EXCLUDED.instructor_id, is_published = EXCLUDED.is_published, updated_at = NOW();
INSERT INTO public.courses (id, title, slug, description, category, level, thumbnail_url, instructor_id, is_published, created_at, updated_at) VALUES ('d0000000-0000-0000-0000-000000000009'::UUID, 'Artificial Intelligence Fundamentals', 'artificial-intelligence-fundamentals', 'Foundational study of classical artificial intelligence: intelligent agents, state-space formulation, uninformed vs informed heuristic search (A*, IDA*), adversarial game playing (Minimax, Alpha-Beta pruning), constraint satisfaction problems (CSP), and propositional logic knowledge bases.', 'AI & Data Science', 'Intermediate', 'https://images.unsplash.com/photo-1677442136019-21780ecad995?q=80&w=800&auto=format&fit=crop', 'c6086584-6cf7-43a4-ae1b-6bd3bb3f7293'::UUID, true, NOW(), NOW()) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, level = EXCLUDED.level, thumbnail_url = EXCLUDED.thumbnail_url, instructor_id = EXCLUDED.instructor_id, is_published = EXCLUDED.is_published, updated_at = NOW();
INSERT INTO public.courses (id, title, slug, description, category, level, thumbnail_url, instructor_id, is_published, created_at, updated_at) VALUES ('d0000000-0000-0000-0000-000000000010'::UUID, 'Machine Learning Foundations', 'machine-learning-foundations', 'Rigorous introduction to statistical machine learning: supervised learning, linear and logistic regression, gradient descent optimization, bias-variance tradeoff, regularization (L1/L2), decision trees, ensemble methods (Random Forests, Gradient Boosting), SVMs, unsupervised clustering (K-Means, GMM), and PCA dimensionality reduction.', 'AI & Data Science', 'Intermediate', 'https://images.unsplash.com/photo-1555949963-ff9fe0c870eb?q=80&w=800&auto=format&fit=crop', 'c6086584-6cf7-43a4-ae1b-6bd3bb3f7293'::UUID, true, NOW(), NOW()) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, level = EXCLUDED.level, thumbnail_url = EXCLUDED.thumbnail_url, instructor_id = EXCLUDED.instructor_id, is_published = EXCLUDED.is_published, updated_at = NOW();
INSERT INTO public.courses (id, title, slug, description, category, level, thumbnail_url, instructor_id, is_published, created_at, updated_at) VALUES ('d0000000-0000-0000-0000-000000000011'::UUID, 'Generative AI and Large Language Models', 'generative-ai-large-language-models', 'Comprehensive study of modern generative architectures: self-attention mechanisms, Transformer encoders and decoders, pretraining objectives (Causal LM, Masked LM), scaling laws, instruction fine-tuning, RLHF, Parameter-Efficient Fine-Tuning (LoRA, QLoRA), Retrieval-Augmented Generation (RAG), and hallucination mitigation.', 'AI & Data Science', 'Advanced', 'https://images.unsplash.com/photo-1620712943543-bcc4688e7485?q=80&w=800&auto=format&fit=crop', 'c6086584-6cf7-43a4-ae1b-6bd3bb3f7293'::UUID, true, NOW(), NOW()) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, level = EXCLUDED.level, thumbnail_url = EXCLUDED.thumbnail_url, instructor_id = EXCLUDED.instructor_id, is_published = EXCLUDED.is_published, updated_at = NOW();
INSERT INTO public.courses (id, title, slug, description, category, level, thumbnail_url, instructor_id, is_published, created_at, updated_at) VALUES ('d0000000-0000-0000-0000-000000000012'::UUID, 'Engineering Mathematics and Linear Algebra', 'engineering-mathematics-linear-algebra', 'Undergraduate engineering mathematics foundation: vector spaces, subspaces, linear independence, matrix factorizations (LU, QR, SVD), eigenvalues and eigenvectors, multivariable calculus, Taylor approximations, and ordinary differential equations.', 'Engineering & Math', 'Intermediate', 'https://images.unsplash.com/photo-1635070041078-e363dbe005cb?q=80&w=800&auto=format&fit=crop', 'c6086584-6cf7-43a4-ae1b-6bd3bb3f7293'::UUID, true, NOW(), NOW()) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, level = EXCLUDED.level, thumbnail_url = EXCLUDED.thumbnail_url, instructor_id = EXCLUDED.instructor_id, is_published = EXCLUDED.is_published, updated_at = NOW();
INSERT INTO public.courses (id, title, slug, description, category, level, thumbnail_url, instructor_id, is_published, created_at, updated_at) VALUES ('d0000000-0000-0000-0000-000000000013'::UUID, 'Digital Logic and Computer Organization', 'digital-logic-computer-organization', 'Hardware engineering from boolean gates to microarchitecture: Boolean algebra, Karnaugh maps, combinational logic (Adders, Multiplexers, ALUs), sequential circuits (Flip-Flops, FSMs), RISC-V instruction set architecture, 5-stage classic pipeline, hazard mitigation, and cache memory hierarchy.', 'Engineering & Math', 'Intermediate', 'https://images.unsplash.com/photo-1518770660439-4636190af475?q=80&w=800&auto=format&fit=crop', 'c6086584-6cf7-43a4-ae1b-6bd3bb3f7293'::UUID, true, NOW(), NOW()) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, level = EXCLUDED.level, thumbnail_url = EXCLUDED.thumbnail_url, instructor_id = EXCLUDED.instructor_id, is_published = EXCLUDED.is_published, updated_at = NOW();
INSERT INTO public.courses (id, title, slug, description, category, level, thumbnail_url, instructor_id, is_published, created_at, updated_at) VALUES ('d0000000-0000-0000-0000-000000000014'::UUID, 'Data Analytics with Python', 'data-analytics-with-python', 'Practical data science and analytics engineering: NumPy vectorized computations, Pandas data wrangling and aggregation, exploratory data analysis (EDA), data visualization with Matplotlib and Seaborn, hypothesis testing, A/B testing statistical methodology, and interactive dashboards.', 'Data Science', 'Beginner', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?q=80&w=800&auto=format&fit=crop', 'c6086584-6cf7-43a4-ae1b-6bd3bb3f7293'::UUID, true, NOW(), NOW()) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, level = EXCLUDED.level, thumbnail_url = EXCLUDED.thumbnail_url, instructor_id = EXCLUDED.instructor_id, is_published = EXCLUDED.is_published, updated_at = NOW();
INSERT INTO public.courses (id, title, slug, description, category, level, thumbnail_url, instructor_id, is_published, created_at, updated_at) VALUES ('d0000000-0000-0000-0000-000000000015'::UUID, 'Technical Communication and Problem Solving', 'technical-communication-problem-solving', 'Essential professional engineering capabilities: structured technical writing (RFCs, design documents, postmortems), API documentation, root cause analysis (5 Whys, Ishikawa diagrams), cognitive bias mitigation, engineering trade-off frameworks, and collaborative technical presentation.', 'Professional Development', 'Beginner', 'https://images.unsplash.com/photo-1522071820081-009f0129c71c?q=80&w=800&auto=format&fit=crop', 'c6086584-6cf7-43a4-ae1b-6bd3bb3f7293'::UUID, true, NOW(), NOW()) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, level = EXCLUDED.level, thumbnail_url = EXCLUDED.thumbnail_url, instructor_id = EXCLUDED.instructor_id, is_published = EXCLUDED.is_published, updated_at = NOW();
